(async()=>{try{const response=await fetch('/app-original.js',{cache:'no-store'});if(!response.ok)throw new Error(`app.js load failed: ${response.status}`);let source=await response.text();const before='await this.simulateLoading();await this.initializeEngine();';const after='await Promise.all([this.simulateLoading(),this.initializeEngine()]);';if(!source.includes(before))throw new Error('loading sequence not found');source=source.replace(before,after);(0,eval)(source);}catch(error){console.error('Bootstrap failed:',error);const loading=document.getElementById('loading-screen');const main=document.getElementById('main-screen');if(loading)loading.classList.remove('active');if(main)main.classList.add('active');}})();
